import java.util.*;

public class Main {
    private enum State {
        OUTSIDE, INSIDE
    }

    private static void processOutside(String segment, int[] maxHolder) {
        for (String word : segment.split("_")) {
            if (word.length() > maxHolder[0]) {
                maxHolder[0] = word.length();
            }
        }
    }

    private static void processInside(String segment, int[] countHolder) {
        for (String word : segment.split("_")) {
            if (!word.isEmpty()) {
                countHolder[0]++;
            }
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        String s = sc.next();
        State state = State.OUTSIDE;
        StringBuilder sb = new StringBuilder();
        int[] maxOutSide = {0};
        int[] nbrInside = {0};
        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            if (c == '(') {
                if (state == State.OUTSIDE) {
                    processOutside(sb.toString(), maxOutSide);
                }
                state = State.INSIDE;
                sb.setLength(0);
            } else if (c == ')') {
                state = State.OUTSIDE;
                processInside(sb.toString(), nbrInside);
                sb.setLength(0);
            } else {
                sb.append(c);
            }
        }
        processOutside(sb.toString(), maxOutSide);
        System.out.println(maxOutSide[0] + " " + nbrInside[0]);
    }
}
